ReplicatedClass.Get = function(self, key, ...)
    local ci = self.ClientItem
    local localVM = ci and ci.ClientFighter and ci.ClientFighter.IsLocalPlayer
    if localVM then
        local base = ci.Name or self._rivalsBase or self.Name
        if key == "Charm" and base and _G.SelectedCharms[base] then
            local chosen = _G.SelectedCharms[base]
            if chosen == "None" then return nil else return { Name = chosen } end
        end
        if key == "Wrap" and base and _G.SelectedWraps[base] then
            local chosen = _G.SelectedWraps[base]
            if chosen == "None" then return nil else return { Name = chosen } end
        end
    end
    return _G.OldReplicatedGet(self, key, ...)
end

