local function GetSkinAssetModel(skinName)
    local scripts = player:FindFirstChild("PlayerScripts")
    if not scripts then return nil end
    local assets = scripts:FindFirstChild("Assets")
    if not assets then return nil end
    local vms = assets:FindFirstChild("ViewModels")
    if not vms then return nil end

    for _, desc in ipairs(vms:GetDescendants()) do
        if desc:IsA("Model") and desc.Name == skinName then
            return desc
        end
    end
    return nil
end

local function GetActiveClientViewModel(weaponName)
    for _, obj in ipairs(getgc(true)) do
        if type(obj) == "table" and rawget(obj, "ItemModel") and rawget(obj, "_is_equipped") == true then
            local ok, ci = pcall(function() return obj.ClientItem end)
            if ok and ci then
                local isLocal = false
                pcall(function() isLocal = ci.ClientFighter and ci.ClientFighter.IsLocalPlayer or false end)
                if isLocal and (not weaponName or ci.Name == weaponName) then
                    return obj
                end
            end
        end
    end
    return nil
end

local function RebuildViewModel(vmObj, skinName)
    local srcModel = GetSkinAssetModel(skinName)
    if not srcModel then
        return false, "Could not find asset model for " .. skinName
    end

    local modelRoot = vmObj.Model
    if not modelRoot then
        return false, "No active viewmodel Model container found"
    end

    local rootPart = modelRoot.PrimaryPart
    if not rootPart then
        return false, "PrimaryPart (RootPart) of viewmodel not found"
    end

    if vmObj.ItemModel then
        vmObj.ItemModel:Destroy()
    end

    local newSkin = srcModel:Clone()
    newSkin.Name = "ItemVisual"
    newSkin.Parent = modelRoot
    vmObj.ItemModel = newSkin

    for _, child in ipairs(rootPart:GetChildren()) do
        if child:IsA("Motor6D") and (child.Name:find("ItemVisual", 1, true) or child.Name:find("Primary", 1, true)) then
            child:Destroy()
        end
    end

    for _, armName in ipairs({"RightArm", "LeftArm"}) do
        local arm = modelRoot:FindFirstChild(armName)
        if arm then
            for _, child in ipairs(arm:GetChildren()) do
                if child:IsA("Model") then
                    child:Destroy()
                end
            end
        end
    end

    vmObj._arm_submodels = {}
    vmObj._animation_context_submodels = {}
    vmObj._submodel_boundingbox_attachments = {}
    vmObj._muzzle_attachments = {}

    vmObj._rivalsBase = vmObj._rivalsBase or (vmObj.ClientItem and vmObj.ClientItem.Name) or vmObj.Name
    vmObj.Info = ItemLibrary.ViewModels[skinName] or vmObj.Info
    vmObj._root_part_offset_inverse = (vmObj.Info.RootPartOffset or CFrame.identity):Inverse()
    vmObj.Name = skinName

    local cframe_2 = nil
    local identity_3 = CFrame.identity

    for _, model_2 in ipairs(newSkin:GetChildren()) do
        if model_2.Name == "_fake" then
            vmObj._can_wrap_left_arm = model_2:FindFirstChild("LeftArmWrapped") ~= nil
            vmObj._can_wrap_right_arm = model_2:FindFirstChild("RightArmWrapped") ~= nil
            task.defer(model_2.Destroy, model_2)
        else
            model_2.PrimaryPart = model_2:FindFirstChild("Primary")
            if not model_2.PrimaryPart then
                model_2.PrimaryPart = model_2:FindFirstChildOfClass("BasePart")
            end

            if model_2.PrimaryPart then
                cframe_2 = cframe_2 or model_2.PrimaryPart.CFrame
                local isArm = model_2.Name == "_right_arm" and "RightArm" or (model_2.Name == "_left_arm" and "LeftArm" or nil)

                if isArm then
                    vmObj._arm_submodels[model_2] = {
                        ["OriginalScale"] = model_2:GetScale(),
                        ["HideInThirdPerson"] = model_2:GetAttribute("HideInThirdPerson")
                    }
                    local armPart = modelRoot[isArm]
                    model_2.Parent = armPart
                    model_2:PivotTo(armPart.CFrame)

                    local weld = Instance.new("WeldConstraint")
                    weld.Part0 = armPart
                    weld.Part1 = model_2.PrimaryPart
                    weld.Parent = model_2.PrimaryPart
                else
                    local motor = Instance.new("Motor6D")
                    motor.Part0 = rootPart
                    motor.Part1 = model_2.PrimaryPart
                    motor.Name = "ItemVisual[\"" .. model_2.Name .. "\"]"
                    motor.C0 = model_2:GetAttribute("C0") or model_2.PrimaryPart.CFrame:ToObjectSpace(cframe_2):Inverse() * identity_3
                    motor.C1 = model_2:GetAttribute("C1") or CFrame.identity
                    motor.Parent = rootPart
                end

                for _, desc in ipairs(model_2:GetDescendants()) do
                    if desc:IsA("BasePart") then
                        desc.CastShadow = false
                        desc.CanCollide = false
                        desc.CanTouch = false
                        desc.CanQuery = false
                        desc.Massless = true
                        if desc ~= model_2.PrimaryPart then
                            local weld = Instance.new("WeldConstraint")
                            weld.Part0 = model_2.PrimaryPart
                            weld.Part1 = desc
                            weld.Parent = model_2.PrimaryPart
                            desc.Anchored = false
                        end
                    end
                end

                model_2.PrimaryPart.Anchored = false

                if not isArm then
                    model_2.PrimaryPart.Name = model_2.Name .. "Primary"
                    model_2:PivotTo(rootPart.CFrame)

                    local animContexts = model_2:GetAttribute("AnimationContexts")
                    if animContexts and animContexts ~= "" then
                        vmObj._animation_context_submodels[model_2] = {}
                        for partName in string.gmatch(animContexts, "([^,%s]+)") do
                            table.insert(vmObj._animation_context_submodels[model_2], partName)
                        end
                    end

                    vmObj._submodel_boundingbox_attachments[model_2] = {}
                    local bbCFrame, bbSize = model_2:GetBoundingBox()
                    for idx, cornerOffset in ipairs(BOX_CORNERS) do
                        local attachment = Instance.new("Attachment")
                        attachment.Name = "_boundingbox" .. idx
                        attachment.Parent = model_2.PrimaryPart
                        attachment.WorldCFrame = bbCFrame * CFrame.new(bbSize * cornerOffset)
                        table.insert(vmObj._submodel_boundingbox_attachments[model_2], attachment)
                    end
                end
            end
        end
    end

    vmObj._aim_position_attachment = modelRoot:FindFirstChild("_aim_position", true)
    vmObj._aim_lookat_attachment = modelRoot:FindFirstChild("_aim_lookat", true)
    vmObj._center_attachment = modelRoot:FindFirstChild("_center", true)
    vmObj._scope_glare_attachment = modelRoot:FindFirstChild("_scope_glare", true)
    vmObj.AimingAnimationEnabled = (vmObj._aim_position_attachment ~= nil and vmObj._aim_lookat_attachment ~= nil)

    vmObj._scope_glare_gui1 = nil
    vmObj._scope_glare_gui2 = nil
    if vmObj._scope_glare_attachment then
        local ui = player.PlayerScripts:FindFirstChild("UserInterface")
        local g1 = ui and ui:FindFirstChild("ScopeGlareGui1")
        local g2 = ui and ui:FindFirstChild("ScopeGlareGui2")
        if g1 and g2 then
            vmObj._scope_glare_gui1 = g1:Clone()
            vmObj._scope_glare_gui1.Enabled = false
            vmObj._scope_glare_gui1.Parent = vmObj._scope_glare_attachment
            vmObj._scope_glare_gui2 = g2:Clone()
            vmObj._scope_glare_gui2.Enabled = false
            vmObj._scope_glare_gui2.Parent = vmObj._scope_glare_attachment
        end
    end

    local MuzzleFlashes = player.PlayerScripts.Assets.Misc.MuzzleFlashes
    for _, desc in ipairs(modelRoot:GetDescendants()) do
        if desc.Name == "_muzzle" then
            table.insert(vmObj._muzzle_attachments, desc)
            desc:ClearAllChildren()

            local MuzzleFlashParticlesName = desc:GetAttribute("MuzzleFlashParticlesName")
            local particleFolder = MuzzleFlashParticlesName and MuzzleFlashes:FindFirstChild(MuzzleFlashParticlesName)
                or MuzzleFlashes:FindFirstChild(vmObj.Name)
                or MuzzleFlashes:FindFirstChild(vmObj.ClientItem.Name)
                or MuzzleFlashes.Default

            if particleFolder and particleFolder:FindFirstChild("Attachment") then
                for _, emitter in ipairs(particleFolder.Attachment:GetChildren()) do
                    emitter:Clone().Parent = desc
                end
            end
        end
    end

    vmObj._charm_attachment_model = newSkin:FindFirstChild("_charm_attachment_model", true)
    vmObj._charm_pivot_attachment = vmObj._charm_attachment_model and vmObj._charm_attachment_model:FindFirstChild("_charm_pivot_attachment", true) or newSkin:FindFirstChild("_charm_pivot_attachment", true)

    vmObj._charm_sub_model = nil
    if vmObj._charm_pivot_attachment then
        for _, model_2 in ipairs(newSkin:GetChildren()) do
            if vmObj._charm_pivot_attachment:IsDescendantOf(model_2) then
                vmObj._charm_sub_model = model_2
                break
            end
        end
    end

    if vmObj.Charm then
        pcall(function() vmObj.Charm:Destroy() end)
        vmObj.Charm = nil
    end

    local equippedCharm = vmObj:Get("Charm")
    if equippedCharm and vmObj._charm_pivot_attachment then
        local modules = player.PlayerScripts:WaitForChild("Modules")
        local CharmModule = require(modules:WaitForChild("Charm"))
        local CharmsFolder = modules:WaitForChild("Charms")

        local charmClass = CharmsFolder:FindFirstChild(equippedCharm.Name, true)
        local charmReq = charmClass and require(charmClass) or CharmModule

        local ok, newCharm = pcall(function()
            return charmReq.new(vmObj, equippedCharm, vmObj._charm_pivot_attachment)
        end)
        if ok and newCharm then
            vmObj.Charm = newCharm
            newCharm:SetParent(vmObj.Model)
        end
    end

    if type(vmObj._UpdateSubModelVisibility) == "function" then
        vmObj:_UpdateSubModelVisibility()
    end
    if type(vmObj._UpdateLocalTransparencyModifiers) == "function" then
        vmObj:_UpdateLocalTransparencyModifiers()
    end
    if type(vmObj._UpdateWrap) == "function" then
        vmObj:_UpdateWrap()
    end
    if type(vmObj.SetArmsData) == "function" then
        vmObj:SetArmsData(nil, nil, nil)
    end

    return true, "Live viewmodel rebuilt successfully"
end

local function ApplyCustomization(weaponName)
    local skinName = _G.SelectedSkins[weaponName] or weaponName
    local charmName = _G.SelectedCharms[weaponName] or "None"

    local vmObj = GetActiveClientViewModel(weaponName)
    if vmObj then
        local ok, err = RebuildViewModel(vmObj, skinName)
        if ok then
            Notify("Applied changes live to: " .. weaponName, false)
        else
            Notify("Rebuild failed: " .. tostring(err), true)
        end
    else
        Notify("Changes saved. Equip " .. weaponName .. " to apply.", false)
    end
end

