local function UpdateUIDropdownsForWeapon(weaponName)
    if isUpdatingUI then return end
    if not (Options.SkinDropdown and Options.CharmDropdown) then return end
    isUpdatingUI = true

    local skins = skinsByWeapon[weaponName] or { weaponName }

    Options.SkinDropdown:SetValues(skins)

