-- Authoritative "in an active match" check (the same source the match-timer used):
-- DuelController:GetDuel(you) returns a live duel ONLY during a match (nil in lobby), and
-- MatchmakingController:IsMatchmadeDuelOver() flips true the instant the match ends. IsInDuel/
-- IsInShootingRange were the bug: the lobby counts as a shooting range and IsInDuel lingers.
-- Cached ~0.2s so the per-player ESP/aim loops don't call GetDuel every frame.
local LOBBY_ENV = utf8.char(0x7FF)
local function envInMatch()
    local ch = player.Character
    local e = (ch and ch:GetAttribute("EnvironmentID")) or player:GetAttribute("EnvironmentID")
    return e ~= nil and e ~= LOBBY_ENV
end

local _mAt, _mVal = 0, false
local function inMatch()
    if tick() - _mAt < 0.2 then return _mVal end
    _mAt = tick()
    local over = false
    if MatchmakingController then
        local ok, o = pcall(function() return MatchmakingController:IsMatchmadeDuelOver() end)
        over = ok and o == true
    end
    local v = false
    if not over then
        local SC = (_G.RivalsHub and _G.RivalsHub.SafeCall) or pcall
        if DuelController then
            local ok, d = SC(function() return DuelController:GetDuel(player) end)
            if ok then v = d ~= nil else v = envInMatch() end
        else
            v = envInMatch()
        end
    end
    _mVal = v
    return v
end
C.InMatch = inMatch

local function isEnemy(plr)
    if plr == player then return false end
    if not inMatch() then return false end
    local char = plr.Character
    if not char then return false end
    local hum = char:FindFirstChildOfClass("Humanoid")
    if not (hum and hum.Health > 0) then return false end
    -- keep only opponents in YOUR duel: same EnvironmentID (other duels shown in the arena differ)
    local mc = player.Character
    local myEnv = mc and mc:GetAttribute("EnvironmentID")
    local enEnv = char:GetAttribute("EnvironmentID")
    if myEnv and enEnv and myEnv ~= enEnv then return false end
    local a, b = mc and mc:GetAttribute("TeamID"), char:GetAttribute("TeamID")
    if a and b and a == b then return false end
    return true
end

local function blocked(char, pos)
    return #cam:GetPartsObscuringTarget({ pos }, { player.Character, char }) > 0
end

