        C._origRGet = ReplicatedClass.Get
        ReplicatedClass.Get = function(self, key, ...)
            -- Spoof CheaterMode ONLY for the split second we (re)arm auto-shoot, never globally.
            -- Holding it true all the time bled into the duel/match-end state (the DuelController
            -- caches CheaterMode) and kept ESP/inMatch alive after a match. The native auto-shoot
            -- only reads CheaterMode inside _ToggleAutoShoot, so a momentary spoof is enough.
            if C._spoofCheater and key == "CheaterMode" then
                local lf = FighterController and FighterController.LocalFighter
                if lf and self == lf then return true end
            end
            return C._origRGet(self, key, ...)
        end
    end
end)
-- Wrap _ToggleAutoShoot so CheaterMode is spoofed true ONLY while it runs -- whether WE call it
-- or the game re-calls it on equip/spawn/etc. That keeps auto-shoot armed with instant reaction,
-- while CheaterMode stays false everywhere else so it never poisons the duel/ESP state.
pcall(function()
    if MC and MC._ToggleAutoShoot and not C._origToggle then
        C._origToggle = MC._ToggleAutoShoot
        MC._ToggleAutoShoot = function(self, ...)
            if not C.TriggerOn then return C._origToggle(self, ...) end
            C._spoofCheater = true
            local ok, a, b = pcall(C._origToggle, self, ...)
            C._spoofCheater = false
            if ok then return a, b end
        end
    end
end)
local function armAutoShoot()
    local SC = (_G.RivalsHub and _G.RivalsHub.SafeCall) or pcall
    SC(function() if MC and MC._ToggleAutoShoot then MC:_ToggleAutoShoot() end end)
end
local function setTrigger(on) C.TriggerOn = on; armAutoShoot() end
-- re-arm if the game clears the connection (e.g. on respawn/equip) while we're on
C._conns.trigwatch = RS.Heartbeat:Connect(function()
    if C.TriggerOn and MC and not MC._auto_shoot_connection then armAutoShoot() end
end)

-- Trigger aim assist: while the trigger is on, softly hold the crosshair on the nearest
-- enemy inside the FOV so the game's auto-shoot keeps firing (that "holds fast shooting
-- when looking at a player" feel). Soft/high-smoothness = sticky, not a hard snap.
C._conns.trigaim = RS.RenderStepped:Connect(function()
    if not (C.TriggerOn and C.TriggerAim and inMatch()) then return end
    if not (CamCtrl and CamCtrl.SetRotation and CamCtrl.Rotation) then return end
    local center = cam.ViewportSize / 2
    local best, bestD = nil, C.TriggerAimFOV
    for _, plr in ipairs(Players:GetPlayers()) do
        if isEnemy(plr) then
            local char = plr.Character
            local head = char and char:FindFirstChild("Head")
            if head then
                local sp, on = cam:WorldToViewportPoint(head.Position)
                if on then
                    local d = (Vector2.new(sp.X, sp.Y) - center).Magnitude
                    if d < bestD then bestD, best = d, head end
                end
            end
        end
    end
    if best then
        local goalP, goalY = CFrame.lookAt(cam.CFrame.Position, best.Position):ToOrientation()
        local cur = CamCtrl.Rotation
        local a = 1 / math.clamp(C.TriggerAimSmooth, 1, 30)
        local dY = (goalY - cur.Y + math.pi) % (math.pi * 2) - math.pi
        local nP = math.clamp(cur.X + (goalP - cur.X) * a, -1.569, 1.569)
        local nY = cur.Y + dY * a
        CamCtrl:SetRotation(Vector2.new(nP, nY))
    end
end)

-- Trigger V2: NO aim movement, NO firing by us. We redirect the game's OWN auto-shoot
-- detection ray (Utility:Raycast along your look vector) onto the nearest player in the FOV,
-- so its can_autoshoot() thinks your crosshair is on a target and the game fires at its
-- natural fast rate. Your real shot still uses your camera aim (GetCameraData) -- bullets go
-- where YOU point, it just never stops firing while a player is on your screen.
pcall(function()
    if C._v2hooked then return end
    local Utility = require(ReplicatedStorage.Modules.Utility)
    if not (Utility and Utility.Raycast) then return end
    C._v2hooked = true
    C._origRaycast = Utility.Raycast
    Utility.Raycast = function(self, origin, endpoint, maxDist, ...)
        if C.TriggerOn and C.TriggerV2 then
            local newEnd
            pcall(function()
                if typeof(origin) == "Vector3" and typeof(endpoint) == "Vector3" and typeof(maxDist) == "number" and maxDist > 0 then
                    local camCF = cam.CFrame
                    if (origin - camCF.Position).Magnitude < 1 then
                        local dir = endpoint - origin
                        if dir.Magnitude > 0 and dir.Unit:Dot(camCF.LookVector) > 0.999 then
                            local center = cam.ViewportSize / 2
                            local bestD, bestPos = C.TriggerV2FOV, nil
                            for _, plr in ipairs(Players:GetPlayers()) do
                                if isEnemy(plr) then
                                    local char = plr.Character
                                    local hp = char and (char:FindFirstChild("Head") or char:FindFirstChild("HumanoidRootPart"))
                                    if hp then
                                        local sp, on = cam:WorldToViewportPoint(hp.Position)
                                        if on then
                                            local d = (Vector2.new(sp.X, sp.Y) - center).Magnitude
                                            if d < bestD then bestD, bestPos = d, hp.Position end
                                        end
                                    end
                                end
                            end
                            if bestPos then newEnd = origin + (bestPos - origin).Unit * maxDist end
                        end
                    end
                end
            end)
            if newEnd then endpoint = newEnd end
        end
        return C._origRaycast(self, origin, endpoint, maxDist, ...)
    end
end)

-- No Recoil: force camera shake off + zero the live gun's viewmodel/camera-displacement
-- kick (Wildcat etc. carry ShootCameraDisplacementRecoil). Steadies the view; Rivals never
-- pushes your aim on fire, so it doesn't change where bullets land.
C._recoilOrig = C._recoilOrig or {}
local function nrApply()
    pcall(function()
        if CamCtrl then
            if C.NoRecoil then
                if C._realShake == nil then C._realShake = CamCtrl._shake_enabled end
                CamCtrl._shake_enabled = false
            elseif C._realShake ~= nil then
                CamCtrl._shake_enabled = C._realShake; C._realShake = nil
            end
        end
    end)
    local lf = FighterController and FighterController.LocalFighter
    if lf then
        local items = {}
        pcall(function() if lf.EquippedItem then items[#items + 1] = lf.EquippedItem end end)
        pcall(function() if type(lf.Items) == "table" then for _, it in ipairs(lf.Items) do items[#items + 1] = it end end end)
        local zeros = { ShootRecoil = 0, ShootCameraDisplacementRecoil = Vector2.zero, ShootCameraDisplacementRecoilWhileAiming = Vector2.zero }
        for _, it in ipairs(items) do
            local info = it.Info
            if type(info) == "table" then
                for field, zero in pairs(zeros) do
                    if info[field] ~= nil then
                        C._recoilOrig[info] = C._recoilOrig[info] or {}
                        if C._recoilOrig[info][field] == nil then C._recoilOrig[info][field] = info[field] end
                        info[field] = C.NoRecoil and zero or C._recoilOrig[info][field]
                    end
                end
            end
        end
    end
end
local function setNoRecoil(on) C.NoRecoil = on; nrApply() end
C._conns.norecoil = RS.Heartbeat:Connect(function()
    if C.NoRecoil and tick() - (C._nrAt or 0) > 0.5 then C._nrAt = tick(); nrApply() end
end)

C._unload = function()
    C.TriggerOn = false
    C.TriggerV2 = false
    local SC = (_G.RivalsHub and _G.RivalsHub.SafeCall) or pcall
    SC(function() if MC and MC._ToggleAutoShoot then MC:_ToggleAutoShoot() end end)
    C.NoRecoil = false; pcall(nrApply)
    C.NoFlash, C.NoFire, C.NoSmoke = false, false, false
    C.SilentOn, C.AimOn, C.ESPOn, C.ChamsOn = false, false, false, false
    if C._aimBound then pcall(function() RS:UnbindFromRenderStep("RivalsAim") end) C._aimBound = false end
    for _, c in pairs(C._conns) do pcall(function() c:Disconnect() end) end
    C._conns = {}
    for plr in pairs(esp) do cleanupPlayer(plr) end
    for plr in pairs(highlights) do cleanupPlayer(plr) end
    if fovCircle then pcall(function() fovCircle:Remove() end) end
    if trigCircle then pcall(function() trigCircle:Remove() end) end
    pcall(function() chamsBin:Destroy() end)
end

