pcall(function() EnemyController = require(player.PlayerScripts.Controllers.EnemyController) end)
if not FighterController then return end

local SHIFT_MAX, MARGIN, TRACER_LIFE = 22, 2.5, 1.5

local W = { On = false, FOV = 250, ShowFOV = true, Tracers = true, target = nil, tmodel = nil, conns = {}, tracers = {}, alive = true }

local K = {}
for i = 0, 5 do K[i] = utf8.char(i) end

local function decode(t)
    return CFrame.new(t[K[0]], t[K[1]], t[K[2]]) * CFrame.fromEulerAnglesYXZ(t[K[3]], t[K[4]], t[K[5]])
end

local function encode(cf)
    local rx, ry, rz = cf:ToEulerAnglesYXZ()
    return { [K[0]] = cf.X, [K[1]] = cf.Y, [K[2]] = cf.Z, [K[3]] = rx, [K[4]] = ry, [K[5]] = rz }
end

local function cam() return workspace.CurrentCamera end

local function myEnv()
    local c = player.Character
    return (c and c:GetAttribute("EnvironmentID")) or player:GetAttribute("EnvironmentID")
end

local function hitboxOf(m)
    return m:FindFirstChild("HitboxHead") or m:FindFirstChild("HitboxBody")
        or m:FindFirstChild("Head") or m:FindFirstChild("HumanoidRootPart")
end

local function alive(m)
    local hum = m:FindFirstChildOfClass("Humanoid")
    return hum ~= nil and hum.Health > 0
end

local function entityOf(m)
    local e
    pcall(function() local f = FighterController:GetFighter(m); e = f and f.Entity end)
    if not e and EnemyController then pcall(function() e = EnemyController:GetEnemy(m) end) end
    return e
end

local function targets()
    local list, seen = {}, {}
    local env, team = myEnv(), player:GetAttribute("TeamID")
    local me = player.Character
    for _, plr in ipairs(Players:GetPlayers()) do
        local c = plr.Character
        if plr ~= player and c and c.Parent and alive(c) then
            local t = plr:GetAttribute("TeamID")
            local e = c:GetAttribute("EnvironmentID") or plr:GetAttribute("EnvironmentID")
            local sameTeam = team ~= nil and t ~= nil and t == team
            local otherEnv = env ~= nil and e ~= nil and e ~= env
            if not sameTeam and not otherEnv then seen[c] = true; list[#list + 1] = c end
        end
    end
    pcall(function()
        local lf = FighterController.LocalFighter
        local params = lf and lf:GetEntityLookupParams()
        local lenv = lf and lf:Get("EnvironmentID")
        if not params then return end
        for _, m in ipairs(CollectionService:GetTagged("Entity")) do
            if m ~= me and not seen[m] and m:FindFirstChildOfClass("Humanoid") and alive(m) then
                local ent = entityOf(m)
                local ok, valid = pcall(function() return params:IsValidTarget(ent) and ent:Get("EnvironmentID") == lenv end)
                if ent and ok and valid then seen[m] = true; list[#list + 1] = m end
            end
        end
    end)
    return list
end

local function mapList()
    local env
    pcall(function() env = FighterController.LocalFighter:Get("EnvironmentID") end)
    return CollectionService:GetTagged("RaycastWhitelist" .. (env or ""))
end

local function castTagged(from, to, list)
    if #list == 0 then return nil end
    local p = RaycastParams.new()
    p.FilterType = Enum.RaycastFilterType.Include
    p.FilterDescendantsInstances = list
    return workspace:Raycast(from, to - from, p)
end

local function castSolid(from, to, model)
    local ex = { cam() }
    for _, pl in ipairs(Players:GetPlayers()) do if pl.Character then ex[#ex + 1] = pl.Character end end
    for _, n in ipairs({ "HurtEffect", "ShootingRangeEntities" }) do
        local f = workspace:FindFirstChild(n)
        if f then ex[#ex + 1] = f end
    end
    if model then ex[#ex + 1] = model end
    local p = RaycastParams.new()
    p.FilterType = Enum.RaycastFilterType.Exclude
    p.FilterDescendantsInstances = ex
    for _ = 1, 8 do
        local r = workspace:Raycast(from, to - from, p)
        if not r then return nil end
        if r.Instance.CanCollide or r.Instance.Transparency < 0.95 then return r end
        ex[#ex + 1] = r.Instance
        p.FilterDescendantsInstances = ex
    end
    return nil
end

local function clear(from, to, model, list)
    return not (castTagged(from, to, list) or castSolid(from, to, model))
end

local function needShift(from, to, model, list)
    local function one(fn)
        if not fn(from, to) then return 0 end
        local back = fn(to, from)
        if not back then return 0 end
        return (from - to).Magnitude - back.Distance + MARGIN
    end
    return math.max(one(function(f, t) return castTagged(f, t, list) end), one(function(f, t) return castSolid(f, t, model) end))
end

local function predicted(hb, model)
    local tp = hb.Position
    local root = model and model:FindFirstChild("HumanoidRootPart")
    local v = root and root.AssemblyLinearVelocity or Vector3.new()
    if v.Magnitude > 60 then v = v.Unit * 60 end
    local lead = 0.15
    pcall(function() lead = math.clamp(player:GetNetworkPing() + 0.1, 0.05, 0.35) end)
    return tp, tp + v * lead
end

local function sees(from, tp, tpred, model, list)
    if not clear(from, tp, model, list) then return false end
    return (tpred - tp).Magnitude < 0.5 or clear(from, tpred, model, list)
end

local circle = (Drawing ~= nil) and Drawing.new("Circle") or nil
if circle then
    circle.Thickness, circle.NumSides, circle.Filled = 1, 64, false
    circle.Transparency, circle.Color, circle.Visible = 0.6, Color3.fromRGB(255, 255, 255), false
end

local stickyHb, stickyM, stickyAt = nil, nil, 0
W.conns.target = RunService.RenderStepped:Connect(function()
    local c = cam()
    if not c then return end
    local center = c.ViewportSize / 2
    if circle then
        circle.Visible = W.On and W.ShowFOV
        circle.Position, circle.Radius = center, W.FOV
    end
    if not W.On then W.target, W.tmodel = nil, nil return end
    local best, bestD, bestM
    for _, m in ipairs(targets()) do
        local hb = hitboxOf(m)
        if hb and hb:IsDescendantOf(workspace) then
            local sp = c:WorldToViewportPoint(hb.Position)
            if sp.Z > 0 then
                local d = (Vector2.new(sp.X, sp.Y) - center).Magnitude
                if d < W.FOV and (not bestD or d < bestD) then best, bestD, bestM = hb, d, m end
            end
        end
    end
    if best then
        stickyHb, stickyM, stickyAt = best, bestM, tick()
    elseif stickyHb and stickyHb:IsDescendantOf(workspace) and tick() - stickyAt < 1.5 then
        best, bestM = stickyHb, stickyM
    end
    W.target, W.tmodel = best, bestM
end)

local function muzzle(lf)
    local ok, p = pcall(function() return lf.EquippedItem.ViewModel:GetMuzzlePosition() end)
    if ok and typeof(p) == "Vector3" then return p end
    if ok and typeof(p) == "CFrame" then return p.Position end
    local cf = cam().CFrame
    return cf.Position + cf.LookVector * 1.5 - cf.UpVector * 0.4
end

local function killTracer(tr)
    for _, x in ipairs(tr.parts) do pcall(function() x:Destroy() end) end
    W.tracers[tr] = nil
end

local function placeTracer(tr, phase)
    for i = 0, tr.n do
        local t = i / tr.n
        local off = tr.perp * (0.18 * math.sin(math.pi * t) * math.sin(t * tr.len / 2.5 * 2 * math.pi - phase))
        tr.atts[i].WorldPosition = tr.from + tr.vec * t + off
    end
end

local function drawTracer(from, to)
    local vec = to - from
    local len = vec.Magnitude
    if len < 0.5 then return end
    local count, oldest = 0, nil
    for tr in pairs(W.tracers) do
        count = count + 1
        if not oldest or tr.t0 < oldest.t0 then oldest = tr end
    end
    if count >= 30 and oldest then killTracer(oldest) end
    local dir = vec.Unit
    local perp = dir:Cross(cam().CFrame.LookVector)
    if perp.Magnitude < 0.05 then perp = dir:Cross(Vector3.new(0, 1, 0)) end
    perp = perp.Magnitude > 0.05 and perp.Unit or Vector3.new(1, 0, 0)
    local n = math.clamp(math.floor(len / 2.5), 6, 24)
    local terrain = workspace.Terrain
    local tr = { from = from, vec = vec, len = len, perp = perp, n = n, t0 = tick(), atts = {}, beams = {}, parts = {} }
    for i = 0, n do
        local a = Instance.new("Attachment")
        a.Parent = terrain
        tr.atts[i] = a
        tr.parts[#tr.parts + 1] = a
    end
    for i = 1, n do
        local b = Instance.new("Beam")
        b.Attachment0, b.Attachment1 = tr.atts[i - 1], tr.atts[i]
        b.FaceCamera, b.LightEmission, b.LightInfluence, b.Segments = true, 1, 0, 1
        b.Width0, b.Width1 = 0.05 + 0.03 * ((i - 1) / n), 0.05 + 0.03 * (i / n)
        b.Parent = terrain
        tr.beams[i] = b
        tr.parts[#tr.parts + 1] = b
    end
    local dot = Instance.new("Part")
    dot.Shape, dot.Size, dot.Material = Enum.PartType.Ball, Vector3.new(0.3, 0.3, 0.3), Enum.Material.Neon
    dot.Anchored, dot.CanCollide, dot.CanQuery, dot.CanTouch, dot.CastShadow = true, false, false, false, false
    dot.CFrame = CFrame.new(to)
    dot.Parent = cam()
    tr.dot = dot
    tr.parts[#tr.parts + 1] = dot
    placeTracer(tr, 0)
    W.tracers[tr] = true
end

W.conns.tracers = RunService.RenderStepped:Connect(function()
    if next(W.tracers) == nil then return end
    local now = tick()
    for tr in pairs(W.tracers) do
        local el = now - tr.t0
        local k = el / TRACER_LIFE
        if k >= 1 then
            killTracer(tr)
        else
            local a = 0.45 + 0.55 * (k < 0.6 and 0 or (k - 0.6) / 0.4)
            placeTracer(tr, el * 9)
            for i = 1, tr.n do
                local t0, t1 = (i - 1) / tr.n, i / tr.n
                tr.beams[i].Transparency = NumberSequence.new(math.min(1, a + (1 - t0) * 0.35), math.min(1, a + (1 - t1) * 0.35))
                tr.beams[i].Color = ColorSequence.new(Color3.fromHSV((t0 * 0.85 + el * 0.5) % 1, 0.7, 1), Color3.fromHSV((t1 * 0.85 + el * 0.5) % 1, 0.7, 1))
            end
            tr.dot.Transparency = math.min(1, a + 0.1)
            tr.dot.Color = Color3.fromHSV((0.85 + el * 0.5) % 1, 0.7, 1)
        end
    end
end)

local function rewrite(lf, data)
    if not W.On then return data end
    if type(data) ~= "table" or type(data[K[0]]) ~= "table" or type(data[K[1]]) ~= "table" then return data end
    local hb, model = W.target, W.tmodel
    if not (hb and hb:IsDescendantOf(workspace)) then return data end
    local okO, origin = pcall(decode, data[K[0]])
    if not okO then return data end
    local head = origin.Position
    local list = mapList()
    local tp, tpred = predicted(hb, model)
    local oPos
    if sees(head, tp, tpred, model, list) then
        oPos = head
    else
        local len = (tp - head).Magnitude
        local cap = math.max(0, math.min(SHIFT_MAX, len - 2))
        local need = needShift(head, tp, model, list)
        if need <= cap then
            local L = (tp - head).Unit
            local s = need
            while s <= cap + 0.01 do
                local o = head + L * s
                if sees(o, tp, tpred, model, list) then oPos = o break end
                s = s + 2
            end
        end
    end
    if not oPos then return data end
    local out = {}
    for k, v in pairs(data) do out[k] = v end
    out[K[0]] = encode(CFrame.lookAt(oPos, tp))
    out[K[1]] = encode(CFrame.lookAt(oPos, tp))
    out[K[2]] = hb
    out[K[3]] = encode(hb.CFrame:ToObjectSpace(CFrame.lookAt(tp, tp + (oPos - tp).Unit)))
    return out
end

local hookedLF, origGCD
local function install(lf)
    local orig = lf.GetCameraData
    if type(orig) ~= "function" then return end
    hookedLF, origGCD = lf, orig
    lf.GetCameraData = function(self, ...)
        local res = orig(self, ...)
        if select("#", ...) == 0 and self == hookedLF then
            local it = self.EquippedItem
            if it and it.Info and it.Info.IsRaycast then
                local ok, out = pcall(rewrite, self, res)
                if ok and out then return out end
            end
        end
        return res
    end
end

local function uninstall()
    if hookedLF and not pcall(rawset, hookedLF, "GetCameraData", nil) then
        pcall(function() hookedLF.GetCameraData = origGCD end)
    end
    hookedLF, origGCD = nil, nil
end

local hookedItems = setmetatable({}, { __mode = "k" })
local function hookItem(it)
    if not it or hookedItems[it] then return end
    local orig = it._ShootEffect
    if type(orig) ~= "function" then return end
    hookedItems[it] = orig
    it._ShootEffect = function(self, results, ...)
        if W.alive and W.Tracers and type(results) == "table" then
            pcall(function()
                local from = muzzle(FighterController.LocalFighter)
                for _, v in pairs(results) do
                    if type(v) == "table" and typeof(v[K[0]]) == "Vector3" then drawTracer(from, v[K[0]]) end
                end
            end)
        end
        return orig(self, results, ...)
    end
end

W.conns.watch = RunService.Heartbeat:Connect(function()
    local lf = FighterController.LocalFighter
    if lf and lf ~= hookedLF then
        uninstall()
        install(lf)
    end
    if lf and lf.EquippedItem then pcall(hookItem, lf.EquippedItem) end
end)

