function W.Unload()
    W.alive, W.On = false, false
    uninstall()
    for it, orig in pairs(hookedItems) do
        if not pcall(rawset, it, "_ShootEffect", nil) then pcall(function() it._ShootEffect = orig end) end
    end
    for _, c in pairs(W.conns) do pcall(function() c:Disconnect() end) end
    W.conns = {}
    if circle then pcall(function() circle:Remove() end) end
    for tr in pairs(W.tracers) do killTracer(tr) end
    _G.RivalsWallbang = nil
end

