pcall(function()
repeat task.wait() until game:IsLoaded()

local Library = _G.__ObsidianLib
if not (Library and _G.RivalsHub and _G.RivalsHub.GetTab) then return end
local Tab = _G.RivalsHub.GetTab("Suggestions", "message-square")
local Opt = Library.Options
local HttpService = game:GetService("HttpService")
local Players = game:GetService("Players")
local lp = Players.LocalPlayer

local function notify(m) Library:Notify({ Title = "COMBO_WICK", Description = tostring(m), Time = 3 }) end

local FEEDBACK_URL     = "https://v0-secure-discord-proxy.vercel.app/api/v2sender"
local FEEDBACK_VERSION = "rivals-hub-1.0"
local _request = request or (syn and syn.request) or http_request
local function fbTrim(s) return (tostring(s or ""):gsub("^%s*(.-)%s*$", "%1")) end
local function fbHWID()
    local ok, id = pcall(function() return game:GetService("RbxAnalyticsService"):GetClientId() end)
    if ok and type(id) == "string" and id ~= "" then return id end
    return tostring(lp and lp.UserId or 0)
end
local FB_HWID = fbHWID()
local FB_ERRMAP = {
    empty = "The message is empty.", no_links = "Links are not allowed.",
    too_long = "The message is too long (500 characters maximum).",
    rate_limited = "You have reached the limit of 3 messages. Please try again later.",
    busy = "The server is busy. Please try again.", banned = "You are not allowed to send feedback.",
    discord_error = "Sending failed. Please try again.", network = "Network error.",
    no_request = "Your executor cannot send requests.", bad_response = "The server returned an unexpected response.",
    unreachable = "Your executor cannot reach the server (TLS error). Please try a different executor.",
}
local function sendFeedback(ftype, msg)
    if not _request then return false, "no_request" end
    local ok, res = pcall(function()
        return _request({
            Url = FEEDBACK_URL, Method = "POST",
            Headers = { ["Content-Type"] = "application/json" },
            Body = HttpService:JSONEncode({
                type = ftype, message = msg, hwid = FB_HWID,
                placeId = tostring(game.PlaceId), username = lp and lp.Name or "?",
                version = FEEDBACK_VERSION,
            }),
        })
    end)
    if not ok or not res then return false, "network" end
    if type(res) == "string" then return false, "unreachable" end
    if type(res) ~= "table" then return false, "network" end
    local code = res.StatusCode or res.status_code or res.Status or res.status
    if type(code) == "number" and code ~= 200 and code ~= 201 and code ~= 204 then return false, "http_" .. tostring(code) end
    local body = res.Body or res.body
    if type(body) ~= "string" or body == "" then return false, "bad_response" end
    local dok, data = pcall(function() return HttpService:JSONDecode(body) end)
    if not dok or type(data) ~= "table" then return false, "bad_response" end
    if data.success == true then return true end
    return false, tostring(data.error or "unknown")
end

local FG = Tab:AddLeftGroupbox("Suggestions / Help", "message-square")
FG:AddDropdown("FeedbackType", { Text = "Type", Values = { "Suggestion", "Bug", "Help" }, Default = "Suggestion" })
FG:AddInput("FeedbackMsg", { Default = "", Numeric = false, Finished = false, ClearTextOnFocus = false, Text = "Message", Placeholder = "Type your message (500 characters maximum, no links)" })
local fbStatus = FG:AddLabel("", true)
local FEEDBACK_COOLDOWN, lastFeedback = 20, 0
FG:AddButton({
    Text = "Send",
    Func = function()
        local now = tick()
        if now - lastFeedback < FEEDBACK_COOLDOWN then
            pcall(function() fbStatus:SetText(string.format("Please wait %d seconds before sending again.", math.ceil(FEEDBACK_COOLDOWN - (now - lastFeedback)))) end)
            return
        end
        local ftype = tostring((Opt.FeedbackType and Opt.FeedbackType.Value) or "Suggestion"):lower()
        local msg = fbTrim((Opt.FeedbackMsg and Opt.FeedbackMsg.Value) or "")
        if msg == "" then pcall(function() fbStatus:SetText("The message is empty.") end); return end
        if #msg > 500 then pcall(function() fbStatus:SetText("The message is too long (500 characters maximum).") end); return end
        local low = msg:lower()
        if low:find("http", 1, true) or low:find("discord.gg", 1, true) or low:find("www.", 1, true) or low:find(".gg/", 1, true) then
            pcall(function() fbStatus:SetText("Links are not allowed.") end); return
        end
        pcall(function() fbStatus:SetText("Sending...") end)
        task.spawn(function()
            local sok, err = sendFeedback(ftype, msg)
            if sok then
                lastFeedback = tick()
                pcall(function() fbStatus:SetText("Sent. Thank you!") end)
                pcall(function() Opt.FeedbackMsg:SetValue("") end)
                notify("Your feedback was sent. Thank you!")
            else
                pcall(function() fbStatus:SetText(FB_ERRMAP[err] or ("Failed to send: " .. tostring(err))) end)
            end
        end)
    end,
})
FG:AddLabel("Maximum 3 messages per hour. No links or mentions.", true)

local HelpGroup = Tab:AddRightGroupbox("Help / FAQ", "life-buoy")
HelpGroup:AddLabel("Have a suggestion or found a bug?\nChoose a type, type your message, and press Send.", true)

end)

pcall(function()
repeat task.wait() until game:IsLoaded()

local Library = _G.__ObsidianLib
if not (Library and _G.RivalsHub and _G.RivalsHub.GetTab) then return end
local ReplicatedStorage = game:GetService("ReplicatedStorage")
local Workspace = game:GetService("Workspace")
local Lighting = game:GetService("Lighting")
local RunService = game:GetService("RunService")

local Utility
pcall(function() Utility = require(ReplicatedStorage.Modules.Utility) end)

_G.RivalsPerf = _G.RivalsPerf or {}
local P = _G.RivalsPerf
if P.ReduceLag == nil then P.ReduceLag = false end
if P.NoTextures == nil then P.NoTextures = false end

if Utility and P._oldPlay == nil then
    P._oldPlay = Utility.PlayParticles
    Utility.PlayParticles = function(...)
        if P.ReduceLag then return end
        return P._oldPlay(...)
    end
end

local function stripEffects(o)
    if o:IsA("ParticleEmitter") or o:IsA("Trail") then pcall(function() o.Enabled = false end)
    elseif o:IsA("Smoke") or o:IsA("Fire") or o:IsA("Sparkles") then pcall(function() o:Destroy() end)
    elseif o:IsA("BasePart") then pcall(function() o.CastShadow = false end) end
end
local function stripTextures(o)
    if o:IsA("Decal") or o:IsA("Texture") then pcall(function() o.Transparency = 1 end)
    elseif o:IsA("BasePart") then pcall(function() o.Material = Enum.Material.SmoothPlastic; o.Reflectance = 0 end) end
end
local function sweep(fn)
    task.spawn(function()
        local n = 0
        for _, o in ipairs(Workspace:GetDescendants()) do
            fn(o); n = n + 1
            if n % 500 == 0 then RunService.Heartbeat:Wait() end
        end
    end)
end

local savedShadows, savedFog, savedQuality
local effConn, texConn

local function setReduce(on)
    P.ReduceLag = on
    if on then
        if savedShadows == nil then savedShadows = Lighting.GlobalShadows end
        if savedFog == nil then savedFog = Lighting.FogEnd end
        pcall(function() if savedQuality == nil then savedQuality = settings().Rendering.QualityLevel end end)
        pcall(function() Lighting.GlobalShadows = false end)
        pcall(function() Lighting.FogEnd = 9e9 end)
        pcall(function() settings().Rendering.QualityLevel = Enum.QualityLevel.Level01 end)
        for _, e in ipairs(Lighting:GetDescendants()) do if e:IsA("PostEffect") then pcall(function() e.Enabled = false end) end end
        pcall(function() local t = Workspace.Terrain; t.WaterWaveSize = 0; t.WaterWaveSpeed = 0; t.WaterReflectance = 0; t.WaterTransparency = 1 end)
        sweep(stripEffects)
        if not effConn then effConn = Workspace.DescendantAdded:Connect(function(o) if P.ReduceLag then stripEffects(o) end end) end
    else
        if effConn then effConn:Disconnect(); effConn = nil end
        pcall(function() if savedShadows ~= nil then Lighting.GlobalShadows = savedShadows end end)
        pcall(function() if savedFog ~= nil then Lighting.FogEnd = savedFog end end)
        pcall(function() if savedQuality ~= nil then settings().Rendering.QualityLevel = savedQuality end end)
    end
end

local function setNoTextures(on)
    P.NoTextures = on
    if on then
        sweep(stripTextures)
        if not texConn then texConn = Workspace.DescendantAdded:Connect(function(o) if P.NoTextures then stripTextures(o) end end) end
    else
        if texConn then texConn:Disconnect(); texConn = nil end
    end
end

